{'content': "// Towel Hook for M3 Flat Head Screw
// Designed for strength and 3D printability

$fn = 64;

// Parameters
base_width = 25;
base_height = 40;
base_thickness = 5;
hook_radius = 12;
hook_depth = 25;
screw_hole_dia = 3.5;
countersink_dia = 6.5;

module towel_hook() {
    difference() {
        union() {
            // Main Base Plate (rounded)
            hull() {
                translate([0, 0, 0]) cube([base_width, 1, base_height], center=true);
                translate([0, base_thickness-1.5, 0]) cube([base_width, 1, base_height], center=true);
            }

            // Hook Neck (reinforced part)
            translate([0, base_thickness/2, -base_height/2 + 5])
            rotate([-15, 0, 0])
            translate([0, hook_depth/2, 0])
            cube([15, hook_depth, 10], center=true);

            // The Hook Tip (Upward curve)
            translate([0, base_thickness + hook_depth - 5, -base_height/2 + 8])
            rotate([0, 90, 0])
            cylinder(h=15, r=6, center=true);

            // Fillet/Support under the hook
            translate([0, 0, -base_height/2])
            hull() {
                translate([0, base_thickness/2, 5]) cube([15, base_thickness, 10], center=true);
                translate([0, base_thickness + hook_depth - 10, 8]) sphere(r=6);
            }
        }

        // M3 Screw Hole (centered upper half)
        translate([0, -1, 10]) {
            rotate([-90, 0, 0]) {
                cylinder(h=base_thickness + 5, d=screw_hole_dia);
                // Countersink for flat head screw
                cylinder(h=3, d1=countersink_dia, d2=screw_hole_dia);
            }
        }

        // Trim the bottom to be flat for printing if needed (though we'll print on side)
    }
}

// Rotate for optimal printing (on its side)
rotate([0, -90, 0])
towel_hook();
"}

{'content': '// Heavy-Duty Towel Hook for M3 Flat Head Screw
// Optimized for strength and easy 3D printing without supports

$fn = 64;

// Main Parameters
base_w = 20;       // Width of the base
base_h = 45;       // Height of the base
base_t = 6;        // Thickness of the base
hook_reach = 30;   // How far out it sticks
hook_thick = 10;   // Thickness of the hook arm
screw_y_offset = 12; // Offset from center for screw hole

module towel_hook() {
    difference() {
        union() {
            // 1. Base Plate with rounded ends
            hull() {
                translate([0, base_h/2 - base_w/2, 0]) cylinder(d=base_w, h=base_t);
                translate([0, -(base_h/2 - base_w/2), 0]) cylinder(d=base_w, h=base_t);
            }

            // 2. Main Hook Body (The "J" shape)
            // Created with a hull between base and tip for strength
            hull() {
                // Connection to the base (lower part)
                translate([-base_w/2, -base_h/2 + 5, 0])
                    cube([base_w, 15, base_t + 5]);

                // The furthest point out
                translate([0, 0, hook_reach])
                    rotate([-90, 0, 0])
                    cylinder(d=hook_thick, h=2);
            }

            // 3. The Upturn (The actual hook tip)
            hull() {
                translate([0, 0, hook_reach])
                    rotate([-90, 0, 0])
                    cylinder(d=hook_thick, h=2);

                translate([0, 15, hook_reach + 5])
                    rotate([-90, 0, 0])
                    cylinder(d=hook_thick, h=5);
            }
        }

        // 4. M3 Screw Hole (Countersunk)
        // Positioned in the upper half of the base
        translate([0, screw_y_offset, -1]) {
            // Main shaft
            cylinder(d=3.5, h=base_t + 2);
            // Countersink (standard M3 flat head is ~6mm diameter)
            translate([0, 0, 0])
                cylinder(d1=6.5, d2=3.5, h=3);
        }

        // 5. Flatten the back (just in case of hull overlaps)
        translate([-50, -50, -10]) cube([100, 100, 10]);
    }
}

// Orientation for printing: On its side for maximum strength
// Layer lines will run along the length of the hook.
rotate([0, -90, 0]) 
towel_hook();
'}

{'content': '// Solid Towel Hook for M3 Flat Head Screw
// Designed for strength and support-free printing

$fn = 64;

// Dimensions
base_width = 20;
base_height = 50;
base_thickness = 6;
hook_projection = 35; // Total depth from wall
hook_thickness = 12;
screw_pos_y = 15; // From center

module hook() {
    difference() {
        union() {
            // Rounded Base Plate
            hull() {
                translate([0, base_height/2 - base_width/2, 0]) cylinder(d=base_width, h=base_thickness);
                translate([0, -(base_height/2 - base_width/2), 0]) cylinder(d=base_width, h=base_thickness);
            }

            // Hook Body - Strong triangular/curved profile
            // Sweeping from the bottom of the base up to the tip
            hull() {
                // Large attachment area at the bottom for leverage resistance
                translate([-base_width/2, -base_height/2, 0]) 
                    cube([base_width, 25, base_thickness]);

                // The outer "nose" of the hook
                translate([0, 0, hook_projection - hook_thickness/2])
                    rotate([-90, 0, 0])
                    cylinder(d=hook_thickness, h=2);
            }

            // The Upward Tip to catch the towel
            hull() {
                translate([0, 0, hook_projection - hook_thickness/2])
                    rotate([-90, 0, 0])
                    cylinder(d=hook_thickness, h=2);

                translate([0, 15, hook_projection])
                    sphere(d=hook_thickness);
            }
        }

        // M3 Screw Hole with Countersink (Upper portion)
        translate([0, screw_pos_y, -1]) {
            // Through hole
            cylinder(d=3.5, h=base_thickness + 2);
            // Countersink for M3 flat head (approx 6-6.5mm)
            cylinder(d1=6.8, d2=3.5, h=3.3);
        }

        // Ensure absolutely flat back
        translate([-50, -50, -10]) cube([100, 100, 10]);
    }
}

// Orientation: Print on side for max strength (layers spanning the curve)
rotate([0, -90, 0])
hook();
'}
